const REQUIREMENTS = [{"id":"R1","name":"Online booking","weight":10},{"id":"R2","name":"SMS reminders","weight":6},{"id":"R3","name":"Vietnamese e-invoice","weight":8},{"id":"R4","name":"Open API","weight":4}];
const RATINGS = {"CareSuite":{"R1":1,"R2":0.5,"R3":0,"R4":1},"MediBook":{"R1":1,"R2":1,"R3":0.5,"R4":0},"ClinicOne":{"R1":0.5,"R2":1,"R3":1,"R4":0.5}};
function evaluate(requirements, ratings) {
  var max = requirements.reduce(function (s, r) { return s + r.weight; }, 0);
  var out = [];
  Object.keys(ratings).forEach(function (name) {
    var rt = ratings[name], ok = true, score = 0;
    requirements.forEach(function (r) {
      var v = Object.prototype.hasOwnProperty.call(rt, r.id) ? rt[r.id] : 0;
      if ([0, 0.5, 1].indexOf(v) < 0) ok = false;
      else score += r.weight * v;
    });
    if (ok) out.push({ name: name, score: score, pct: max ? Math.round(score / max * 1000) / 10 : 0 });
  });
  return out.sort(function (a, b) { return b.score - a.score || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0); });
}
const WINNER = evaluate(REQUIREMENTS, RATINGS)[0].name;
